const LaudoGLI = ({ selectedExam, examDetails, formatDateTimeH, patientCode, formatAttendanceOrigin, signatureSignedUrl }) => {
    const [historico, setHistorico] = useState([]);
    const [loadingHistorico, setLoadingHistorico] = useState(true);

    useEffect(() => {
        let isMounted = true;
        const fetchHistorico = async () => {
            if (!selectedExam || !selectedExam.patient_id) {
                if (isMounted) setLoadingHistorico(false);
                return;
            }
            try {
                setLoadingHistorico(true);
                const historyData = await laboratorioLaudosService.buscarHistoricoGLI(selectedExam.patient_id, selectedExam.id);
                if (isMounted) setHistorico(historyData);
            } catch (err) {
                console.error("Erro ao carregar histórico GLI", err);
            } finally {
                if (isMounted) setLoadingHistorico(false);
            }
        };
        fetchHistorico();
        return () => { isMounted = false; };
    }, [selectedExam?.id, selectedExam?.patient_id]);

    // O parâmetro GLICOSE (ou similar)
    const param = examDetails?.find(p => (p.parameter_name || '').toUpperCase().includes('GLICOSE') || (p.parameter_code || '').toUpperCase() === 'GLI' || (p.parameter_name || '').toUpperCase().includes('GLICEMIA')) || examDetails?.[0];

    const rawResult = param ? (param.value_numeric !== null ? param.value_numeric : (param.value_text || '')) : '';
    const valNum = param ? parseHemoNumber(rawResult, param.parameter_code) : NaN;
    const formattedResult = param ? formatHemoResultValue(rawResult, param.parameter_code) : '';

    // Obter referências baseadas na idade (simulada como adulto 10000 dias para simplificar caso falte no payload atual)
    // O ideal é pegar idade do paciente (se não vier no param, usaremos um padrão adulto ou tentar extrair)
    // Como a referência real vem do `param.reference_text`, resolvemos com a lib existente
    const refObj = param ? resolveHemoReference(param.parameter_code, param.reference_text, 10000, 'MALE') : { valid: false };

    // Construção dos dados do Gráfico 2
    const currentDataPoint = {
        date: selectedExam.dataAtendimentoRaw || new Date().toISOString(),
        value: valNum,
        isCurrent: true
    };

    const chartData = useMemo(() => {
        if (isNaN(valNum)) return [];
        const data = [...historico];
        // Formatar as datas do histórico
        const formattedHistory = data.map(h => ({
            rawDate: h.date,
            dateStr: laboratorioLaudosService.formatDateOnly(h.date),
            value: h.value,
            isCurrent: false
        }));

        const current = {
            rawDate: currentDataPoint.date,
            dateStr: 'Atual', // ou a data do exame atual
            value: currentDataPoint.value,
            isCurrent: true
        };

        const allData = [...formattedHistory, current];
        // Já deve estar ordenado, mas garantimos
        allData.sort((a, b) => new Date(a.rawDate) - new Date(b.rawDate));

        return allData;
    }, [historico, valNum, currentDataPoint.date, currentDataPoint.value]);

    const formatDataAtendimento = (dataStr) => {
        if (!dataStr) return '-';
        const d = new Date(dataStr);
        if (isNaN(d.getTime())) return dataStr;
        const dd = String(d.getDate()).padStart(2, '0');
        const mm = String(d.getMonth() + 1).padStart(2, '0');
        const yyyy = d.getFullYear();
        return `${dd}/${mm}/${yyyy}`;
    };

    // Custom Dot para destacar o exame atual
    const CustomDot = (props) => {
        const { cx, cy, payload } = props;
        if (payload.isCurrent) {
            return (
                <svg x={cx - 5} y={cy - 5} width={10} height={10} fill="#2563eb">
                    <circle cx="5" cy="5" r="5" stroke="#fff" strokeWidth="1.5" />
                </svg>
            );
        }
        return (
            <svg x={cx - 4} y={cy - 4} width={8} height={8} fill="#64748b">
                <circle cx="4" cy="4" r="4" stroke="#fff" strokeWidth="1.5" />
            </svg>
        );
    };

    return (
        <div className="laudo-container laudo-especifico laudo-gli">
            {/* CABEÇALHO PADRÃO INSTITUCIONAL */}
            <div className="hemo-report-header">
                <div className="hemo-header-content">
                    <div className="hemo-logo-container">
                        <img src="/assets/logo-bezerros.png" alt="Prefeitura de Bezerros" className="hemo-logo-img" />
                    </div>
                    <div className="hemo-header-text">
                        <h1 className="hemo-header-title">MUNICÍPIO DE BEZERROS</h1>
                        <h2 className="hemo-header-subtitle">SECRETARIA DE SAÚDE</h2>
                        <h3 className="hemo-header-sub-subtitle">Laboratório Municipal de Análises Clínicas</h3>
                    </div>
                </div>
            </div>

            {/* DADOS DO PACIENTE */}
            <div className="hemo-patient-info">
                <div className="hemo-info-row">
                    <div className="hemo-info-col">
                        <span className="hemo-info-label">Paciente:</span>
                        <span className="hemo-info-value" style={{ fontWeight: 'bold' }}>{selectedExam?.pacienteNome?.toUpperCase()}</span>
                    </div>
                    <div className="hemo-info-col hemo-info-col-right">
                        <span className="hemo-info-label">Código:</span>
                        <span className="hemo-info-value">{patientCode || 'N/I'}</span>
                    </div>
                </div>
                <div className="hemo-info-row">
                    <div className="hemo-info-col hemo-info-age">
                        <span className="hemo-info-label">Idade:</span>
                        <span className="hemo-info-value">{selectedExam?.pacienteIdade || '-'}</span>
                    </div>
