                        <span className="hemo-info-value">{selectedExam?.pacienteSexo || '-'}</span>
                    </div>
                    <div className="hemo-info-col hemo-info-col-right">
                        <span className="hemo-info-label">Atendimento:</span>
                        <span className="hemo-info-value">{formatDataAtendimento(selectedExam?.dataAtendimentoRaw || selectedExam?.dataAtendimento)}</span>
                    </div>
                </div>
