                </div>

                {/* Bloco de Resultado Principal */}
                <div style={{ display: 'flex', flexWrap: 'wrap', gap: '30px', alignItems: 'flex-start', marginBottom: '30px' }}>

                    {/* Resultado Destacado */}
                    <div style={{ flex: '1 1 200px', minWidth: '200px', padding: '20px', background: '#f8fafc', border: '1px solid #e2e8f0', borderRadius: '8px', textAlign: 'center' }}>
