                            <span style={{ fontSize: '14px', fontWeight: 600, color: '#475569' }}>{param?.unit || 'mg/dL'}</span>
                        </div>
                    </div>

                    {/* Referência e Gráfico 1 (Régua) */}
                    <div style={{ flex: '2 1 300px', minWidth: '300px' }}>
                        <div style={{ fontSize: '12px', fontWeight: 600, color: '#64748b', textTransform: 'uppercase', letterSpacing: '0.05em', marginBottom: '8px' }}>Valores de Referência</div>
                        <div style={{ fontSize: '13px', color: '#334155', whiteSpace: 'pre-line', marginBottom: '15px' }}>
                            {param?.reference_text || 'Não cadastrada'}
                        </div>

                        {/* Gráfico 1 - Régua (Mesmo modelo do hemograma) */}
                        {refObj.valid && !refObj.isFixed && !isNaN(valNum) && (
                            <div style={{ marginTop: '15px', padding: '15px', border: '1px solid #e2e8f0', borderRadius: '8px', background: '#fff' }}>
