const GraficoHistoricoGLI = ({ historico, refMin, refMax }) => {
    if (!historico || historico.length <= 1) {
        return null;
    }

    const width = 440;
    const height = 135;
    const paddingLeft = 60;
    const paddingRight = 40;
    const paddingTop = 32;
    const paddingBottom = 32;

    const innerWidth = width - paddingLeft - paddingRight;
    const innerHeight = height - paddingTop - paddingBottom;

    const values = historico.map(h => h.value);
    let minValRaw = Math.min(...values);
    let maxValRaw = Math.max(...values);

    if (typeof refMin === 'number' && !isNaN(refMin)) minValRaw = Math.min(minValRaw, refMin);
    if (typeof refMax === 'number' && !isNaN(refMax)) maxValRaw = Math.max(maxValRaw, refMax);

    // Add margin
    const margin = (maxValRaw - minValRaw) * 0.2 || 10;
    const minVal = minValRaw - margin;
    const maxVal = maxValRaw + margin;
    const range = maxVal - minVal;

    const getY = (val) => paddingTop + innerHeight - ((val - minVal) / range) * innerHeight;

    const points = historico.map((h, i) => {
        let x = paddingLeft + (i / (historico.length - 1)) * innerWidth;
        if (historico.length === 2) {
            // Se forem apenas 2 pontos, centraliza um pouco mais para não ficar nos extremos da caixa
            const offset = innerWidth * 0.15;
            x = i === 0 ? paddingLeft + offset : paddingLeft + innerWidth - offset;
        }
        const y = getY(h.value);
        return { ...h, x, y, isLast: i === historico.length - 1 };
    });

    const dateCounts = {};
    points.forEach(p => {
        dateCounts[p.dateText] = (dateCounts[p.dateText] || 0) + 1;
    });

    const pathD = points.map((p, i) => (i === 0 ? `M ${p.x} ${p.y}` : `L ${p.x} ${p.y}`)).join(' ');

    const showRef = typeof refMin === 'number' && !isNaN(refMin) && typeof refMax === 'number' && !isNaN(refMax);

    return (
        <div style={{ marginTop: '20px', maxWidth: `${width}px` }}>
            <div style={{ display: 'flex', alignItems: 'baseline', gap: '8px', marginBottom: '10px', borderBottom: '1px solid #e2e8f0', paddingBottom: '4px' }}>
                <span style={{ fontSize: '11px', fontWeight: 'bold', color: '#334155' }}>RESULTADOS ANTERIORES</span>
                <span style={{ fontSize: '10px', color: '#64748b' }}>Evolução da glicose (mg/dL)</span>
            </div>
            <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} style={{ overflow: 'visible', background: '#fafaf9', display: 'block', borderRadius: '6px', border: '1px solid #f1f5f9' }}>
                {showRef && (
                    <>
                        {/* Banda de Referência */}
                        <rect x={paddingLeft} y={getY(refMax)} width={innerWidth} height={getY(refMin) - getY(refMax)} fill="#f1f5f9" />

                        {/* Guias superiores e inferiores */}
                        <line x1={paddingLeft} y1={getY(refMax)} x2={width - paddingRight} y2={getY(refMax)} stroke="#cbd5e1" strokeWidth="1" strokeDasharray="3 3" />
                        <line x1={paddingLeft} y1={getY(refMin)} x2={width - paddingRight} y2={getY(refMin)} stroke="#cbd5e1" strokeWidth="1" strokeDasharray="3 3" />

                        {/* Labels da Referência - Movidos para a esquerda */}
                        <text x={paddingLeft - 8} y={getY(refMax) + 3} fontSize="9" fill="#94a3b8" textAnchor="end">{refMax}</text>
                        <text x={paddingLeft - 8} y={getY(refMin) + 3} fontSize="9" fill="#94a3b8" textAnchor="end">{refMin}</text>
                    </>
                )}

                {/* Linha de Evolução */}
                <path d={pathD} fill="none" stroke="#334155" strokeWidth="1.8" />

                {/* Pontos e Textos */}
                {points.map((p, i) => (
                    <g key={i}>
                        {/* Círculo */}
                        <circle 
                            cx={p.x} 
                            cy={p.y} 
                            r={p.isLast ? 4 : 3} 
                            fill={p.isLast ? '#0f172a' : '#64748b'} 
                            stroke="#ffffff"
                            strokeWidth="1.5"
                        />

                        {/* Valor acima do ponto - Subiu de 10/12 para 14/16 para não encostar */}
                        <text 
                            x={p.x} 
                            y={p.y - (p.isLast ? 16 : 14)} 
                            fontSize={p.isLast ? "12" : "11"} 
                            fill={p.isLast ? '#0f172a' : '#475569'} 
                            textAnchor="middle" 
                            fontWeight={p.isLast ? 'bold' : '500'}
                        >
                            {String(p.value).replace('.', ',')}
                        </text>

                        {/* Data abaixo do ponto */}
                        <text 
                            x={p.x} 
                            y={height - 16} 
                            fontSize="10" 
                            fill={p.isLast ? '#334155' : '#64748b'} 
                            textAnchor="middle" 
                            fontWeight={p.isLast ? '600' : 'normal'}
                        >
                            {p.dateText}
                        </text>

                        {/* Hora caso haja mais de 1 no mesmo dia */}
                        {dateCounts[p.dateText] > 1 && p.timeText && (
                            <text x={p.x} y={height - 4} fontSize="9" fill="#94a3b8" textAnchor="middle">
                                {p.timeText}
                            </text>
                        )}
                    </g>
                ))}
            </svg>
        </div>
    );
};

