// Controle do drawer de seleção de exames
const [drawerOpen, setDrawerOpen] = useState(false);
const laudoRef = useRef(null);

// ETAPA 5.1A - Cache Completo
const [completeExamDataById, setCompleteExamDataById] = useState({});
const [completeDataStatus, setCompleteDataStatus] = useState('idle');
const [completeDataError, setCompleteDataError] = useState(null);
const signatureCache = useRef({});
const historicoCache = useRef({});
const latestPrepareRequest = useRef(0);
const completeExamDataRef = useRef({});

useEffect(() => {
    const protocolExams = selectedProtocol?.exams || [];
    const printableExams = protocolExams.filter(ex => selectedExamIds.has(ex.id));

    if (printableExams.length === 0) {
        setCompleteDataStatus('idle');
        setCompleteDataError(null);
        return;
    }

    const allowedHistoryExams = ['GLI', 'HGT', 'HDL', 'LDL', 'VLDL', 'COL', 'TRI', 'CRE', 'URE', 'ACU', 'TGO', 'TGP', 'GGT', 'FAL', 'BIL', 'VHS'];

    // Verifica se já está tudo no cache
    const allCached = printableExams.every(ex => {
        const data = completeExamDataRef.current[ex.id];
        if (!data || !data.details) return false;
        if (allowedHistoryExams.includes(ex.exameCodigo) && !data.history) return false;
        if (ex.responsible_signature_path && !data.signatureSignedUrl) return false;
        return true;
    });

    if (allCached) {
        if (completeDataStatus !== 'ready') setCompleteDataStatus('ready');
        return;
    }

    const currentRequestId = ++latestPrepareRequest.current;
    setCompleteDataStatus('loading');
    setCompleteDataError(null);

    const prepareData = async () => {
        try {
            // 1. Detalhes (em lote)
            const missingDetailIds = printableExams
                .filter(ex => !completeExamDataRef.current[ex.id] || !completeExamDataRef.current[ex.id].details)
                .map(ex => ex.id);

            let fetchedDetails = {};
            if (missingDetailIds.length > 0) {
                fetchedDetails = await laboratorioLaudosService.carregarDetalhesLaudosLote(missingDetailIds);
            }

            // 2. Assinaturas (caminhos únicos)
            const missingSignaturesPaths = [...new Set(
                printableExams
                    .filter(ex => ex.responsible_signature_path && (!completeExamDataRef.current[ex.id]?.signatureSignedUrl && !signatureCache.current[ex.responsible_signature_path]))
                    .map(ex => ex.responsible_signature_path)
            )];

            await Promise.all(missingSignaturesPaths.map(async (path) => {
                if (!path) return;
                try {
                    const url = await laboratorioLaudosService.getLaboratorioSignatureSignedUrl(path);
                    signatureCache.current[path] = url;
                } catch (e) {
                    console.warn('Falha ao carregar signature', path, e);
                }
            }));

            // 3. Históricos
            const currentTimestamp = new Date().getTime();
            const historyPromises = printableExams
                .filter(ex => {
                    if (!allowedHistoryExams.includes(ex.exameCodigo)) return false;
                    if (completeExamDataRef.current[ex.id]?.history) return false;
                    const cacheKey = `${ex.id}_${ex.patient_id}`;
                    return !historicoCache.current[cacheKey];
                })
                .map(async (ex) => {
                    const cacheKey = `${ex.id}_${ex.patient_id}`;
                    try {
                        const hist = await laboratorioLaudosService.buscarHistoricoExame(ex.exameCodigo, ex.patient_id, ex.id, currentTimestamp);
                        let finalHistorico = [];
                        if (hist && hist.length > 0) {
                            finalHistorico = [...hist];
                            finalHistorico = finalHistorico.map(h => ({
                                ...h,
                                rawDate: h.rawDate || h.dataAtendimento,
                                value: parseFloat(String(h.value).replace(',', '.'))
                            })).filter(h => !isNaN(h.value));
                            finalHistorico.sort((a, b) => new Date(a.rawDate).getTime() - new Date(b.rawDate).getTime());
                            if (finalHistorico.length <= 1) finalHistorico = [];
                        }
                        historicoCache.current[cacheKey] = finalHistorico;
                    } catch (e) {
                        console.warn('Falha historico', ex.exameCodigo, e);
                        historicoCache.current[cacheKey] = [];
                    }
                });

            await Promise.all(historyPromises);

            if (currentRequestId !== latestPrepareRequest.current) return;

            let hasError = false;
            const errorIds = [];
            const nextState = { ...completeExamDataRef.current };

            printableExams.forEach(ex => {
                const existing = nextState[ex.id] || {};
                const params = fetchedDetails[ex.id] ? fetchedDetails[ex.id].details : existing.details;

                if (!params) {
                    hasError = true;
                    errorIds.push(ex.exameCodigo);
                }

                const cacheKey = `${ex.id}_${ex.patient_id}`;
                const hist = allowedHistoryExams.includes(ex.exameCodigo) 
                    ? (historicoCache.current[cacheKey] || existing.history) 
                    : null;

                const sigPath = ex.responsible_signature_path;
                const sigUrl = sigPath ? (signatureCache.current[sigPath] || existing.signatureSignedUrl) : null;

                nextState[ex.id] = {
                    exam: ex,
                    details: params,
                    parameters: params,
                    history: hist,
                    responsible: ex.responsible_name,
                    signatureSignedUrl: sigUrl
                };
            });

            if (currentRequestId !== latestPrepareRequest.current) return;

            completeExamDataRef.current = nextState;
            setCompleteExamDataById(nextState);

            if (hasError) {
                setCompleteDataError(`Falha ao carregar parâmetros de: ${errorIds.join(', ')}`);
                setCompleteDataStatus('error');
            } else {
                setCompleteDataStatus('ready');
            }
        } catch (error) {
            if (currentRequestId === latestPrepareRequest.current) {
                console.error('Erro na preparação do cache em lote', error);
                setCompleteDataError('Erro interno na preparação');
                setCompleteDataStatus('error');
            }
        }
    };

    prepareData();
}, [selectedProtocol, selectedExamIds, completeDataStatus]);

