const LaboratorioLaudos = () => {

const preparePromiseCache = useRef({});
const completeExamDataRef = useRef({});

// ETAPA 5.2 - Compositor A4 e Medição
const [paginationStatus, setPaginationStatus] = useState('idle'); // idle | measuring | composing | ready | error
const [composedPages, setComposedPages] = useState([]);
const [examHeights, setExamHeights] = useState({});
const measureAreaRef = useRef(null);

    preparePromiseCache.current[preparationKey] = prepareData();
}, [selectedResultIdsKey, activeProtocolKey, activePatientId]);

// Dispara a medição quando entra no modo preview com dados prontos
useEffect(() => {
    if (previewMode !== 'complete' || completeDataStatus !== 'ready') {
        setPaginationStatus('idle');
        return;
    }
    setPaginationStatus('measuring');
}, [previewMode, completeDataStatus, selectedResultIdsKey]);

// Algoritmo de Agrupamento
useLayoutEffect(() => {
    if (paginationStatus === 'measuring' && measureAreaRef.current) {
        const shellNode = measureAreaRef.current.querySelector('.measure-shell');
        const pageNode = measureAreaRef.current.querySelector('.lab-complete-preview-page');
        const nodes = measureAreaRef.current.querySelectorAll('.measure-exam-body');

        const pageHeight = pageNode ? pageNode.offsetHeight : 1122;
        const shellHeight = shellNode ? shellNode.offsetHeight : 250;

        // maxUsableHeight é o espaço vertical livre na folha (desconta header/footer/paddings)
        const maxUsableHeight = pageHeight - shellHeight - 40; 

        const heights = {};
        nodes.forEach(n => {
            const id = n.getAttribute('data-exam-id');
            if (id) {
                heights[id] = n.offsetHeight;
            }
        });

        setExamHeights(heights);

        const orderedSelectedExams = (selectedProtocol?.exams || [])
            .filter(ex => selectedExamIds.has(ex.id))
            .sort((a, b) => {
                const orderDiff = (a.examePrintOrder ?? 999) - (b.examePrintOrder ?? 999);
                if (orderDiff !== 0) return orderDiff;
                const codeDiff = (a.exameCodigo || '').localeCompare(b.exameCodigo || '');
                if (codeDiff !== 0) return codeDiff;
                return (a.id || '').localeCompare(b.id || '');
            });

        const pages = [];
        let currentPage = [];
        let currentHeight = 0;
        let currentSignature = null;

        orderedSelectedExams.forEach(ex => {
            const examData = completeExamDataById[ex.id];
            if (!examData) return;

            const height = heights[ex.id] || 300;
            const sigPath = ex.responsible_signature_path || 'no-sig';
            const isHEMO = ex.exameCodigo === 'HEMO';

            // Regra de exclusividade do Hemograma
            if (isHEMO) {
                if (currentPage.length > 0) {
                    pages.push([...currentPage]);
                    currentPage = [];
                    currentHeight = 0;
                }
                pages.push([examData]);
                currentSignature = null;
                return;
            }

            // Regra de Responsável: quebra página se mudar o assinante
            if (currentPage.length > 0 && currentSignature !== sigPath) {
                pages.push([...currentPage]);
                currentPage = [];
                currentHeight = 0;
            }

            // Regra de Altura
            const gap = currentPage.length > 0 ? 16 : 0;
            if (currentPage.length > 0 && (currentHeight + height + gap > maxUsableHeight)) {
                pages.push([...currentPage]);
                currentPage = [];
                currentHeight = 0;
            }

            currentPage.push(examData);
            currentHeight += height + gap;
            currentSignature = sigPath;
        });

        if (currentPage.length > 0) {
            pages.push(currentPage);
        }

        setComposedPages(pages);
        setPaginationStatus('ready');
    }
}, [paginationStatus, completeExamDataById, selectedProtocol, selectedExamIds]);

