    if (paginationStatus === 'ready' && previewMode === 'complete' && laudoRef.current && !validationCheckDone.current) {
        const renderedPages = laudoRef.current.querySelectorAll('.lab-composed-page');
        let hasViolation = false;
        let newlyFailedExamId = null;

        renderedPages.forEach((page) => {
            if (hasViolation) return;

            const exams = page.querySelectorAll('.lab-composed-exam-wrapper');
            const bottom = page.querySelector('.lab-composed-bottom');

            if (exams.length > 1 && bottom) {
                const lastExam = exams[exams.length - 1];
                const examRect = lastExam.getBoundingClientRect();
                const bottomRect = bottom.getBoundingClientRect();

                // Distância real entre o último exame e a assinatura/rodapé
                const distance = bottomRect.top - examRect.bottom;
                if (distance < 29) { // ~8mm tolerando 1px de diferença de arredondamento
                    const id = lastExam.getAttribute('data-exam-id');
                    if (id && !forceBreakExams.has(id)) {
                        hasViolation = true;
                        newlyFailedExamId = id;
                    }
                }
            }
        });

        if (hasViolation && newlyFailedExamId) {
            console.warn(`Validação DOM falhou. Distância de segurança violada no exame ${newlyFailedExamId}. Forçando repaginação...`);
            setForceBreakExams(prev => new Set([...prev, newlyFailedExamId]));
            setPaginationStatus('measuring');
        } else {
            validationCheckDone.current = true;
        }
    }
}, [paginationStatus, previewMode, forceBreakExams]);

