useLayoutEffect(() => {
    if (paginationStatus === 'validating' && validationRootRef.current) {
        const renderedPages = validationRootRef.current.querySelectorAll('.lab-composed-page');
        let hasViolation = false;
        let newlyFailedExamId = null;
        const limit = Math.max(10, selectedExamIds.size * 2 + 2);

        if (validationAttempts > limit) {
            setPaginationStatus('error');
            return;
        }

        renderedPages.forEach((page, index) => {
            if (hasViolation) return;

            // 1. Validar a altura total da página (scrollHeight > clientHeight + 1)
            if (page.scrollHeight > page.clientHeight + 1) {
                hasViolation = true;
            }

            const examsArea = page.querySelector('.lab-composed-exams');
            if (examsArea && examsArea.scrollHeight > examsArea.clientHeight + 1) {
                hasViolation = true;
            }

            const exams = page.querySelectorAll('.lab-composed-exam-wrapper');
            const bottom = page.querySelector('.lab-composed-bottom');

            if (exams.length > 0 && bottom) {
                const lastExam = exams[exams.length - 1];
                const examRect = lastExam.getBoundingClientRect();
                const bottomRect = bottom.getBoundingClientRect();

                // Distância real entre o último exame e a assinatura/rodapé
                const distance = bottomRect.top - examRect.bottom;
                const safetyGapPx = (8 * 96) / 25.4; // 8mm em px = ~30.23px

                if (distance < Math.floor(safetyGapPx) || hasViolation) {
                    const id = lastExam.getAttribute('data-exam-id');
                    // Somente tentar repaginar se tiver mais de um exame na página
                    // Se só tem 1 exame, e não coube, vai ficar cortado ou estourado, mas é o melhor possível.
                    if (exams.length > 1 && id && !forceBreakExams.has(id)) {
                        hasViolation = true;
                        newlyFailedExamId = id;
                        console.warn(`[Paginação] Validação falhou na página ${index + 1}. Distância: ${distance}px (exame ${id}). scrollHeight: ${page.scrollHeight}, clientHeight: ${page.clientHeight}`);
                    }
                }
            }
        });

        if (hasViolation && newlyFailedExamId) {
            console.warn(`AJUSTE: Movendo exame ${newlyFailedExamId} para a próxima página.`);
            setForceBreakExams(prev => new Set([...prev, newlyFailedExamId]));
            setValidationAttempts(v => v + 1);
            setPaginationStatus('measuring');
        } else if (hasViolation) {
            // Tem violação, mas não dá pra mover (ex: 1 único exame na página que excede o A4)
            console.warn(`[Paginação] Violação detectada, mas não há como repaginar.`);
            setComposedPages(candidatePages);
            setPaginationStatus('ready');
        } else {
            // Válido
            setComposedPages(candidatePages);
            setPaginationStatus('ready');
        }
    }
}, [paginationStatus, candidatePages, forceBreakExams, validationAttempts, selectedExamIds.size]);

