            if (hasViolation || isPendingRender || !page) return;

            if (index === 0 && candidatePages.length === 1 && candidatePages[0].length === 3) {
                const firstCodes = candidatePages[0].map(ex => completeExamDataById[ex.id]?.exam?.exameCodigo || ex.id).join(', ');
                console.log(`COMPOSIÇÃO INICIAL\nPágina 1: ${firstCodes}`);
            }

            const examsArea = page.querySelector('.lab-composed-exams');
            const exams = page.querySelectorAll('.lab-composed-exam-wrapper');
            const bottom = page.querySelector('.lab-composed-bottom');

            // 1. Medir a página completa
            const pageHeight = page.clientHeight;
            const requiredHeight = page.scrollHeight;
            let examsAreaHeight = examsArea ? examsArea.clientHeight : 0;
            let examsAreaScroll = examsArea ? examsArea.scrollHeight : 0;

            // Se os elementos não renderizaram fisicamente ainda, abortamos a validação e aguardamos.
            if (pageHeight === 0 || !bottom || exams.length === 0) {
                isPendingRender = true;
                return;
            }

            let distance = 0;
            let lastExamCode = '';
            let lastExamBottom = 0;
            let bottomTop = 0;

            // A página A4 pode ter pequenas variações (arredondamento, subpixels), não reprovar SÓ por scrollHeight se for mínimo.
            // Mas a validação final será geométrica.
            let isInvalid = requiredHeight > pageHeight + 2; 

            const lastExam = exams[exams.length - 1];
            const examRect = lastExam.getBoundingClientRect();
            const bottomRect = bottom.getBoundingClientRect();

            if (examRect.height === 0 || bottomRect.height === 0) {
                isPendingRender = true;
                return; // Aguardando render real
            }

            const id = lastExam.getAttribute('data-exam-id');
            lastExamCode = completeExamDataById[id]?.exam?.exameCodigo || id;

            lastExamBottom = examRect.bottom;
            bottomTop = bottomRect.top;
            distance = bottomRect.top - examRect.bottom;
            const safetyGapPx = (8 * 96) / 25.4; // 8mm em px = ~30.23px
            const tolerancePx = 2;

            // Validação principal geométrica:
            if (examRect.bottom + safetyGapPx > bottomRect.top + tolerancePx) {
                isInvalid = true;
                console.log(`[PAGINAÇÃO] Invalidação geométrica na página ${index + 1}: examBottom (${examRect.bottom}) + gap (${safetyGapPx}) > bottomTop (${bottomRect.top}) + tol (${tolerancePx})`);
            } else if (isInvalid && exams.length === 1) {
                // Se o scrollHeight exceder um pouco mas a geometria estiver intacta e houver SÓ UM EXAME (como URE isolado),
                // nós perdoamos e não ativamos erro, pois ele cabe.
                isInvalid = false;
                console.log(`[PAGINAÇÃO] Ignorando aviso de scrollHeight na página ${index + 1} pois possui apenas 1 exame e a geometria validou.`);
            } else if (isInvalid && examRect.bottom + safetyGapPx <= bottomRect.top + tolerancePx) {
                // Se a geometria provar que cabe fisicamente, sobrepõe o scrollHeight estrito.
                isInvalid = false;
                console.log(`[PAGINAÇÃO] Ignorando aviso de scrollHeight na página ${index + 1} pois a geometria provou que os exames cabem.`);
            }

            if (isInvalid) {
                let blockReason = (requiredHeight > pageHeight + 2) ? 'scrollHeight excedido' : 'Geometria (exames sobrepõem assinatura)';
                console.log(`VALIDAÇÃO PÁGINA ${index + 1}\nclientHeight: ${pageHeight}\nscrollHeight: ${requiredHeight}\nexamsArea.clientHeight: ${examsAreaHeight}\nexamsArea.scrollHeight: ${examsAreaScroll}\nÚltimo exame bottom: ${lastExamBottom}\nBloco inferior top: ${bottomTop}\nDistância encontrada: ${distance}\nsafetyGap: ${(8 * 96) / 25.4}\nVálida: false\nMotivo da invalidação: ${blockReason}`);
                hasViolation = true;

                if (exams.length > 1) {
                    if (id && !forceBreakExams.has(id)) {
                        newlyFailedExamId = id;
                    }
                }
            } else {
                console.log(`VALIDAÇÃO PÁGINA ${index + 1}\nclientHeight: ${pageHeight}\nscrollHeight: ${requiredHeight}\nexamsArea.clientHeight: ${examsAreaHeight}\nexamsArea.scrollHeight: ${examsAreaScroll}\nÚltimo exame bottom: ${lastExamBottom}\nBloco inferior top: ${bottomTop}\nDistância encontrada: ${distance}\nsafetyGap: ${(8 * 96) / 25.4}\nVálida: true\nMotivo da invalidação: N/A`);
            }
        });

        if (isPendingRender) {
            // Ainda aguardando componentes montarem ou CSS carregar
            // setPaginationStatus('validating'); // Continua validando no próximo render
            return;
        }

        if (hasViolation && newlyFailedExamId) {
            const examCode = completeExamDataById[newlyFailedExamId]?.exam?.exameCodigo || newlyFailedExamId;
            console.log(`MOVENDO\n${examCode}: página atual → página seguinte`);
            setForceBreakExams(prev => new Set([...prev, newlyFailedExamId]));
            setValidationAttempts(v => v + 1);
            setPaginationStatus('measuring');
        } else if (hasViolation) {
            // Tem violação, mas não dá pra mover (ex: 1 único exame na página que excede o A4)
            console.warn(`[Paginação] Exame único que não coube.`);
            setPaginationStatus('error');
        } else {
            // Verificar integridade
            let totalExams = 0;
            const uniqueExams = new Set();
            candidatePages.forEach(p => {
                p.forEach(ex => {
                    totalExams++;
                    uniqueExams.add(ex.id);
                });
            });

            if (totalExams === selectedExamIds.size && uniqueExams.size === selectedExamIds.size) {
                let finalLog = `COMPOSIÇÃO VALIDADA\n`;
                candidatePages.forEach((p, idx) => {
                    const codes = p.map(ex => completeExamDataById[ex.id]?.exam?.exameCodigo || ex.id).join(', ');
                    finalLog += `Página ${idx + 1}: ${codes}\n`;
                });
                finalLog += `Total de exames: ${totalExams}\nExames únicos: ${uniqueExams.size}\nTodas válidas: true`;
                console.log(finalLog);

                setComposedPages(candidatePages);
                setPaginationStatus('ready');
            } else {
                console.error(`[Paginação] Erro de integridade: Exames sumiram. Esperado ${selectedExamIds.size}, encontrado ${totalExams}`);
                setPaginationStatus('error');
            }
        }
    });
});
return () => {
    cancelAnimationFrame(raf1);
};

