                <button className="lab-btn lab-btn-primary" onClick={handleSearch} disabled={loading} style={{ width: '100%', boxSizing: 'border-box', whiteSpace: 'nowrap' }}>
                    {loading ? <Loader2 size={16} className="spin" /> : <Search size={16} />}
                    Filtrar
                </button>
            </div>
        </div>

        {/* Layout Principal */}
        <div className={`lab-main-layout ${selectedExam ? 'has-sidebar' : ''}`}>
            {/* Lista Lateral */}
            <div className={`lab-sidebar ${selectedExam ? 'visible' : ''}`}>
                <div className="lab-card lab-list-container">
                    {loading ? (
                        <div className="lab-empty-state"><Loader2 size={32} className="spin" /><p>Carregando exames...</p></div>
                    ) : filteredResults.length === 0 ? (
                        <div className="lab-empty-state"><FileText size={32} /><p>Nenhum exame encontrado</p></div>
                    ) : (
                        Object.values(groupedProtocols)
                            .sort((a, b) => b.latestEventDate - a.latestEventDate)
                            .map((group) => {
                                // Status consolidado
                                const allLiberado = group.exams.every(ex => (ex.status || '').trim().toUpperCase() === 'CONFERIDO');
                                const protocolStatus = allLiberado ? 'LIBERADO' : 'AGUARDANDO';

                                const isAnyExamSelected = group.exams.some(ex => selectedExam?.id === ex.id);

                                // Ajuste para exibir a origem do atendimento
                                const originLabel = group.attendance_origin 
                                    ? String(group.attendance_origin).toUpperCase().includes('INTERNAÇÃO')
                                        ? 'INT'
                                        : String(group.attendance_origin).toUpperCase().includes('URGÊNCIA') || String(group.attendance_origin).toUpperCase().includes('EMERGÊNCIA')
                                            ? 'URG'
                                            : 'AMB'
                                    : '---';

                                return (
                                    <div 
                                        key={group.protocolo} 
                                        className={`laudos-protocol-group ${isAnyExamSelected ? 'laudos-protocol-group-active' : ''}`}
                                        onClick={() => {
                                            const firstAllowed = group.exams.find(ex => ex.printsOnReport !== false);
                                            if (firstAllowed && selectedExam?.id !== firstAllowed.id) {
                                                handleSelectExam(firstAllowed);
                                            }
                                        }}
                                    >
                                        <div className="laudos-protocol-header">
                                            <div className="laudos-protocol-header-top">
                                                <div className="laudos-protocol-number-wrapper">
                                                    <span className="laudos-protocol-number">{group.protocolo}</span>
                                                    <span className="laudos-protocol-origin">{originLabel}</span>
                                                </div>
                                                <span className={`laudos-protocol-status laudos-protocol-status-${protocolStatus.toLowerCase()}`}>
                                                    {protocolStatus === 'LIBERADO' ? 'LIBERADOS' : 'AGUARDANDO'}
                                                </span>
                                            </div>
                                            <div className="laudos-protocol-patient-info">
                                                <span className="laudos-protocol-patient-name">{group.pacienteNome}</span>
                                                <div className="laudos-protocol-patient-details">
                                                    <span className="laudos-protocol-patient-age">{group.pacienteIdade}</span>
                                                    <span className="laudos-protocol-patient-sex">{group.pacienteSexo}</span>
                                                    {group.convenio && <span className="laudos-protocol-convenio">{group.convenio}</span>}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="laudos-protocol-exams">
                                            {group.exams
                                                .sort((a, b) => {
                                                    const orderA = a.examePrintOrder ?? 999;
                                                    const orderB = b.examePrintOrder ?? 999;
                                                    if (orderA !== orderB) return orderA - orderB;
                                                    return (a.exameCodigo || '').localeCompare(b.exameCodigo || '');
                                                })
                                                .map(ex => {
                                                    const isActive = selectedExam?.id === ex.id;
                                                    const isChecked = selectedExamIds.has(ex.id);
                                                    const exStatus = (ex.status || '').trim().toUpperCase();
                                                    const notPrints = ex.printsOnReport === false;
                                                    const orderLabel = ex.examePrintOrder < 999 
                                                        ? String(ex.examePrintOrder).padStart(2, '0') 
                                                        : '——';

                                                    return (
                                                        <div 
                                                            key={ex.id} 
                                                            className={`laudos-exam-item${isActive ? ' laudos-exam-item-active' : ''}${notPrints ? ' laudos-exam-item-noprint' : ''}`}
                                                            onClick={(e) => {
                                                                e.stopPropagation();
                                                                handleSelectExam(ex);
                                                            }}
                                                        >
                                                            <input 
                                                                type="checkbox" 
                                                                className="laudos-exam-checkbox"
                                                                checked={isChecked}
                                                                disabled={notPrints}
                                                                onClick={(e) => e.stopPropagation()}
                                                                onChange={(e) => {
                                                                    e.stopPropagation();
                                                                    toggleExamSelection(ex);
                                                                }}
                                                                title={notPrints ? "Exame não configurado para impressão em laudo" : "Selecionar para impressão conjunta"}
                                                            />
                                                            <div className="laudos-exam-info">
                                                                <div className="laudos-exam-main-line">
                                                                    <span className="laudos-exam-code">{ex.exameCodigo}</span>
                                                                    <span className="laudos-exam-name">{ex.exameNome}</span>
                                                                </div>
                                                                <div className="laudos-exam-sub-line">
                                                                    <span className="laudos-exam-date">{ex.dataAtendimento}</span>
                                                                    <span className="laudos-exam-order">#{orderLabel}</span>
                                                                    {notPrints && <span className="laudos-exam-noprint-badge">NÃO IMPRIME</span>}
                                                                    {!notPrints && <span className={`laudos-exam-status-dot laudos-exam-status-dot-${exStatus === 'CONFERIDO' ? 'liberado' : 'aguardando'}`} title={exStatus} />}
                                                                </div>
                                                            </div>
                                                        </div>
                                                    );
                                            })}
                                        </div>
                                    </div>
                                );
                            })
                    )}
                </div>
            </div>

            {/* Área Principal (Laudo ou Mensagem) */}
            <div className="lab-main-content">
                {!selectedExam ? (
                    <div className="lab-empty-state" style={{ height: '100%', background: 'white', borderRadius: '8px', border: '1px solid #e2e8f0' }}>
                        <FileText size={48} style={{ color: '#cbd5e1', marginBottom: '1rem' }} />
                        <p>Selecione um exame na lista para visualizar o laudo</p>
                    </div>
                ) : (
                    <>
                        {/* Toolbar superior (dentro da área principal) */}
                        <div className="laudos-action-bar no-print">
                            {/* Esquerda: resumo de seleção e chips */}
                            <div className="laudos-action-bar-left">
                                <span className="laudos-action-counter">
                                    {selectedExamIds.size} de {selectedProtocol?.exams.length ?? 0} exame{(selectedProtocol?.exams.length ?? 0) !== 1 ? 's' : ''} selecionado{selectedExamIds.size !== 1 ? 's' : ''}
                                </span>
                                {/* Chips dos exames selecionados — máximo 4 visíveis */}
                                <div className="laudos-action-chips">
                                    {(() => {
                                        const selected = (selectedProtocol?.exams || []).filter(ex => selectedExamIds.has(ex.id));
                                        const maxChips = 4;
                                        const visible = selected.slice(0, maxChips);
                                        const overflow = selected.length - maxChips;
                                        return (
                                            <>
                                                {visible.map(ex => (
                                                    <span key={ex.id} className="laudos-chip" onClick={() => handleSelectExam(ex)} title={ex.exameNome}>
                                                        {ex.exameCodigo}
                                                    </span>
                                                ))}
                                                {overflow > 0 && (
                                                    <span className="laudos-chip laudos-chip-overflow">+{overflow}</span>
                                                )}
                                            </>
                                        );
                                    })()}
                                </div>
                            </div>

                            {/* Direita: botões de ação */}
                            <div className="laudos-action-bar-right">
                                {selectedExamIds.size > 1 && (
                                    <button 
                                        type="button" 
                                        className="laudos-action-btn laudos-action-btn-secondary"
                                        onClick={() => setPreviewMode(prev => prev === 'individual' ? 'complete' : 'individual')}
                                    >
                                        <FileText size={14} />
                                        {previewMode === 'individual' ? 'Prévia completa' : 'Voltar ao exame'}
                                    </button>
                                )}
                                <button 
                                    type="button" 
                                    className="laudos-action-btn laudos-action-btn-secondary"
                                    onClick={() => setDrawerOpen(true)}
                                >
                                    <SlidersHorizontal size={14} />
                                    Selecionar exames
                                </button>

                                {selectedExamIds.size > 0 && (
                                    <>
                                        <button 
                                            type="button" 
                                            className="laudos-action-btn laudos-action-btn-icon"
                                            onClick={() => window.print()}
                                            disabled={paginationStatus !== 'ready'}
                                            aria-label="Imprimir"
                                            title="Imprimir"
                                        >
                                            <Printer size={15} strokeWidth={2} />
                                        </button>
                                        <button 
                                            type="button" 
                                            className="laudos-action-btn laudos-action-btn-icon"
                                            onClick={handleDownloadPdf}
                                            disabled={generatingPdf || paginationStatus !== 'ready'}
                                            aria-label="Baixar PDF"
                                            title="Baixar PDF"
                                        >
                                            {generatingPdf ? <Loader2 size={15} strokeWidth={2} className="spin" /> : <Download size={15} strokeWidth={2} />}
                                        </button>
                                    </>
                                )}

